static ProducerRecord<String, String> deadLetter(ConsumerRecord<String, String> failed, Throwable error, String dlt) {
    var record = new ProducerRecord<>(dlt, null, failed.key(), failed.value()); // partition from the key
    for (Header h : failed.headers()) record.headers().add(h);                 // keep the producer's headers
    record.headers()
            .add("dlt.original.topic", utf8(failed.topic()))
            .add("dlt.original.partition", utf8(Integer.toString(failed.partition())))
            .add("dlt.original.offset", utf8(Long.toString(failed.offset())))
            .add("dlt.exception.class", utf8(error.getClass().getName()))
            .add("dlt.exception.message", utf8(error.getMessage() == null ? "" : error.getMessage()));
    return record;
}

static byte[] utf8(String s) { return s.getBytes(StandardCharsets.UTF_8); }

