static boolean isTransient(Throwable e) {
    return e instanceof java.net.http.HttpTimeoutException       // the card issuer was slow
            || e instanceof IssuerUnavailableException            // our wrapper for a 503
            || e instanceof java.sql.SQLTransientException;       // lock wait timeout, connection reset
}

void handleWithRetries(ConsumerRecord<String, String> r) throws Exception {
    for (int attempt = 1; ; attempt++) {
        try {
            ledger.apply(Payment.parse(r.value()));
            return;
        } catch (Exception e) {
            if (!isTransient(e) || attempt == 3) throw e;         // permanent, or out of attempts
            Thread.sleep(100L << (attempt - 1));                  // 100 ms, then 200 ms
        }
    }
}

